def partition(groups, n):
    """The groups as sorted lists of members, worked out from find(): elements of one group must share a representative and other groups must not."""
    by_representative = {}
    for element in range(n):
        by_representative.setdefault(groups.find(element), []).append(element)
    return sorted(by_representative.values())
def first_redundant(n, edges):
    """Join the edges one by one; return the first edge whose ends were already together (as [a, b]), or None."""
    groups = UnionFind(n)
    for a, b in edges:
        if not groups.union(a, b):
            return [a, b]
    return None
def long_chain_then_lookups(length, lookups):
    """Join 0-1, 1-2, 2-3, ... one after another, then look up element 0 over and over. A find that walks a long chain each time is too slow."""
    groups = UnionFind(length)
    for i in range(length - 1):
        groups.union(i, i + 1)
    root = groups.find(length - 1)
    for _ in range(lookups):
        if groups.find(0) != root:
            raise AssertionError("elements joined one after another should all be in one group")
    return groups.component_count() == 1
def many_pairs(count):
    """Join 0-1, 2-3, 4-5, ... in a long list of elements. Re-labelling every element on each union is too slow."""
    groups = UnionFind(count)
    for i in range(0, count, 2):
        groups.union(i, i + 1)
    return (groups.component_count(), groups.connected(0, 1), groups.connected(1, 2)) == (count // 2, True, False)
