class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))        # every element starts as its own root
        self.size = [1] * n                 # for a root: how many elements are in its tree
        self.groups = n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]    # path halving: skip a level on the way up
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a, root_b = self.find(a), self.find(b)
        if root_a == root_b:
            return False                    # already one group
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a
        self.parent[root_b] = root_a        # hang the smaller tree under the larger one
        self.size[root_a] += self.size[root_b]
        self.groups -= 1
        return True

    def connected(self, a, b):
        return self.find(a) == self.find(b)

    def component_count(self):
        return self.groups
